package com.mamtrex.hospital.patient; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*; @RestController @RequestMapping("/api/patients") public class PatientController { private final PatientService service; public PatientController(PatientService s){service=s;} public record CreatePatientRequest(@NotBlank String medicalRecordNumber,@NotBlank String fullName,LocalDate dateOfBirth,String sex,String phone,@Email String email,String nationalId,String address){} public record UpdatePatientRequest(@NotBlank String fullName,String phone,@Email String email,String address){} @PostMapping public Patient create(@Valid @RequestBody CreatePatientRequest r){return service.create(r.medicalRecordNumber(),r.fullName(),r.dateOfBirth(),r.sex(),r.phone(),r.email(),r.nationalId(),r.address());} @GetMapping("/{id}") public Patient get(@PathVariable UUID id){return service.get(id);} @GetMapping public List<Patient> list(@RequestParam(required=false) String q){return service.list(q);} @PutMapping("/{id}") public Patient update(@PathVariable UUID id,@Valid @RequestBody UpdatePatientRequest r){return service.update(id,r.fullName(),r.phone(),r.email(),r.address());} }
